import React from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

export default function Navbar() {
  const { user, logout } = useAuth();
  return (
    <nav className="bg-neutral text-white px-8 py-4 flex justify-between items-center shadow-lg border-b-4 border-brand">
      <Link to="/" className="text-2xl font-black tracking-tighter hover:text-brand transition-colors">
        RATE<span className="text-brand">IT</span>.
      </Link>
      <div className="flex items-center gap-6 font-medium text-sm">
        {!user ? (
          <>
            <Link to="/" className="hover:text-brand transition-colors">Login</Link>
            <Link to="/signup" className="bg-brand px-5 py-2 rounded-full hover:bg-brand-dark transition-colors shadow-lg shadow-brand/20">Sign Up</Link>
          </>
        ) : (
          <>
            <span className="hidden md:block text-gray-400">Welcome, <span className="text-white font-bold">{user.name}</span></span>
            <Link to="/dashboard" className="hover:text-brand transition-colors uppercase tracking-wider font-bold">Dashboard</Link>
            <button
              onClick={logout}
              className="bg-gray-800 border border-gray-700 px-4 py-2 rounded-lg hover:bg-brand hover:border-brand transition-all text-xs uppercase font-bold"
            >
              Logout
            </button>
          </>
        )}
      </div>
    </nav>
  );
}
